//! Per-protocol entity tables, generated by `scripts/translation_entities.py`
//! from the official server jars into `data/entities/<protocol>.json`.
//!
//! Entity data is addressed by index and serializer, and both shift between
//! versions: an entity type's indexes are the fields of its class hierarchy,
//! root first, in definition order. Every field carries a key that names the
//! same field in every version (the newest Mojang name, carried back), so
//! converting between two protocols is matching keys.
use crate::data;
use serde_json::Value;
use std::{
    collections::HashMap,
    sync::{Mutex, OnceLock},
};

/// An entity data serializer by what it carries. A `*Holder` kind is a
/// registry entry that may also be sent inline (ID + 1, or 0 and the value),
/// unlike the plain registry ID of the kind without the suffix.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Kind {
    Byte,
    Int,
    Long,
    Float,
    String,
    Component,
    OptionalComponent,
    ItemStack,
    Boolean,
    Rotations,
    BlockPos,
    OptionalBlockPos,
    Direction,
    OptionalUuid,
    BlockState,
    OptionalBlockState,
    CompoundTag,
    Particle,
    Particles,
    VillagerData,
    OptionalUnsignedInt,
    Pose,
    CatVariant,
    CatSoundVariant,
    CowVariant,
    CowSoundVariant,
    WolfVariant,
    WolfVariantHolder,
    WolfSoundVariant,
    FrogVariant,
    PigVariant,
    PigSoundVariant,
    ChickenVariant,
    ChickenSoundVariant,
    ZombieNautilusVariant,
    OptionalGlobalPos,
    PaintingVariant,
    PaintingVariantHolder,
    SnifferState,
    ArmadilloState,
    CopperGolemState,
    WeatheringCopperState,
    Vector3,
    Quaternion,
    ResolvableProfile,
    HumanoidArm,
    DyeColor,
}

impl Kind {
    pub fn parse(name: &str) -> Option<Self> {
        use Kind::*;
        Some(match name {
            "byte" => Byte,
            "int" => Int,
            "long" => Long,
            "float" => Float,
            "string" => String,
            "component" => Component,
            "optional_component" => OptionalComponent,
            "item_stack" => ItemStack,
            "boolean" => Boolean,
            "rotations" => Rotations,
            "block_pos" => BlockPos,
            "optional_block_pos" => OptionalBlockPos,
            "direction" => Direction,
            "optional_uuid" => OptionalUuid,
            "block_state" => BlockState,
            "optional_block_state" => OptionalBlockState,
            "compound_tag" => CompoundTag,
            "particle" => Particle,
            "particles" => Particles,
            "villager_data" => VillagerData,
            "optional_unsigned_int" => OptionalUnsignedInt,
            "pose" => Pose,
            "cat_variant" => CatVariant,
            "cat_sound_variant" => CatSoundVariant,
            "cow_variant" => CowVariant,
            "cow_sound_variant" => CowSoundVariant,
            "wolf_variant" => WolfVariant,
            "wolf_variant_holder" => WolfVariantHolder,
            "wolf_sound_variant" => WolfSoundVariant,
            "frog_variant" => FrogVariant,
            "pig_variant" => PigVariant,
            "pig_sound_variant" => PigSoundVariant,
            "chicken_variant" => ChickenVariant,
            "chicken_sound_variant" => ChickenSoundVariant,
            "zombie_nautilus_variant" => ZombieNautilusVariant,
            "optional_global_pos" => OptionalGlobalPos,
            "painting_variant" => PaintingVariant,
            "painting_variant_holder" => PaintingVariantHolder,
            "sniffer_state" => SnifferState,
            "armadillo_state" => ArmadilloState,
            "copper_golem_state" => CopperGolemState,
            "weathering_copper_state" => WeatheringCopperState,
            "vector3" => Vector3,
            "quaternion" => Quaternion,
            "resolvable_profile" => ResolvableProfile,
            "humanoid_arm" => HumanoidArm,
            "dye_color" => DyeColor,
            _ => return None,
        })
    }

    /// The name the data files use.
    pub fn name(self) -> &'static str {
        use Kind::*;
        match self {
            Byte => "byte",
            Int => "int",
            Long => "long",
            Float => "float",
            String => "string",
            Component => "component",
            OptionalComponent => "optional_component",
            ItemStack => "item_stack",
            Boolean => "boolean",
            Rotations => "rotations",
            BlockPos => "block_pos",
            OptionalBlockPos => "optional_block_pos",
            Direction => "direction",
            OptionalUuid => "optional_uuid",
            BlockState => "block_state",
            OptionalBlockState => "optional_block_state",
            CompoundTag => "compound_tag",
            Particle => "particle",
            Particles => "particles",
            VillagerData => "villager_data",
            OptionalUnsignedInt => "optional_unsigned_int",
            Pose => "pose",
            CatVariant => "cat_variant",
            CatSoundVariant => "cat_sound_variant",
            CowVariant => "cow_variant",
            CowSoundVariant => "cow_sound_variant",
            WolfVariant => "wolf_variant",
            WolfVariantHolder => "wolf_variant_holder",
            WolfSoundVariant => "wolf_sound_variant",
            FrogVariant => "frog_variant",
            PigVariant => "pig_variant",
            PigSoundVariant => "pig_sound_variant",
            ChickenVariant => "chicken_variant",
            ChickenSoundVariant => "chicken_sound_variant",
            ZombieNautilusVariant => "zombie_nautilus_variant",
            OptionalGlobalPos => "optional_global_pos",
            PaintingVariant => "painting_variant",
            PaintingVariantHolder => "painting_variant_holder",
            SnifferState => "sniffer_state",
            ArmadilloState => "armadillo_state",
            CopperGolemState => "copper_golem_state",
            WeatheringCopperState => "weathering_copper_state",
            Vector3 => "vector3",
            Quaternion => "quaternion",
            ResolvableProfile => "resolvable_profile",
            HumanoidArm => "humanoid_arm",
            DyeColor => "dye_color",
        }
    }

    /// The registry a registry-ID kind refers to, by its registry name.
    pub fn registry(self) -> Option<&'static str> {
        use Kind::*;
        Some(match self {
            CatVariant => "cat_variant",
            CatSoundVariant => "cat_sound_variant",
            CowVariant => "cow_variant",
            CowSoundVariant => "cow_sound_variant",
            WolfVariant | WolfVariantHolder => "wolf_variant",
            WolfSoundVariant => "wolf_sound_variant",
            FrogVariant => "frog_variant",
            PigVariant => "pig_variant",
            PigSoundVariant => "pig_sound_variant",
            ChickenVariant => "chicken_variant",
            ChickenSoundVariant => "chicken_sound_variant",
            ZombieNautilusVariant => "zombie_nautilus_variant",
            PaintingVariant | PaintingVariantHolder => "painting_variant",
            _ => return None,
        })
    }

    /// Whether the value is an enum constant sent as its ordinal.
    pub fn is_enum(self) -> bool {
        use Kind::*;
        matches!(
            self,
            Direction
                | Pose
                | SnifferState
                | ArmadilloState
                | CopperGolemState
                | WeatheringCopperState
                | HumanoidArm
                | DyeColor
        )
    }
}

/// One entity data field: its cross-version key and serializer.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Field {
    pub key: &'static str,
    pub kind: Kind,
}

/// One protocol's entity tables.
#[derive(Debug)]
pub struct Tables {
    pub protocol: i32,
    /// Serializer kinds by network ID.
    pub serializers: Vec<Kind>,
    serializer_ids: HashMap<Kind, i32>,
    enums: HashMap<Kind, Vec<&'static str>>,
    /// Every entity type's fields in index order, by type name.
    types: HashMap<&'static str, Vec<Field>>,
    /// The fields every entity has (the root class's).
    root: Vec<Field>,
    /// Particle name -> its options type, for particles that have options.
    particles: HashMap<&'static str, &'static str>,
    /// Entity types this protocol renamed: new name -> old name.
    pub renamed: Vec<(&'static str, &'static str)>,
}

impl Tables {
    fn load(protocol: i32) -> Self {
        let file = data::file(&format!("entities/{protocol}"))
            .unwrap_or_else(|| panic!("no entity data for protocol {protocol}"));
        let text = |value: &'static Value| value.as_str().expect("entity data string");
        let kind = |value: &'static Value| {
            Kind::parse(text(value))
                .unwrap_or_else(|| panic!("unknown serializer kind {value} for {protocol}"))
        };
        let serializers: Vec<Kind> = file["serializers"]
            .as_array()
            .expect("serializers")
            .iter()
            .map(kind)
            .collect();
        let serializer_ids = serializers
            .iter()
            .enumerate()
            .map(|(id, kind)| (*kind, id as i32))
            .collect();
        let enums = file["enums"]
            .as_object()
            .expect("enums")
            .iter()
            .map(|(name, values)| {
                let kind = Kind::parse(name).expect("enum kind");
                let values = values
                    .as_array()
                    .expect("enum values")
                    .iter()
                    .map(text)
                    .collect();
                (kind, values)
            })
            .collect();
        let classes = file["classes"].as_object().expect("classes");
        let fields_of = |class: &str| -> Vec<Field> {
            let mut chain = Vec::new();
            let mut current = Some(class);
            while let Some(name) = current {
                let entry = &classes[name];
                chain.push(entry);
                current = entry["parent"].as_str();
            }
            chain
                .iter()
                .rev()
                .flat_map(|entry| entry["fields"].as_array().expect("fields").iter())
                .map(|field| Field {
                    key: text(&field[0]),
                    kind: kind(&field[1]),
                })
                .collect()
        };
        let types: HashMap<&'static str, Vec<Field>> = file["types"]
            .as_object()
            .expect("types")
            .iter()
            .map(|(name, class)| (name.as_str(), fields_of(text(class))))
            .collect();
        let root = classes
            .iter()
            .find(|(_, entry)| entry["parent"].is_null())
            .map(|(name, _)| fields_of(name))
            .expect("a root class");
        let particles = file["particles"]
            .as_object()
            .expect("particles")
            .iter()
            .map(|(name, options)| (name.as_str(), text(options)))
            .collect();
        let renamed = file["renamed"]
            .as_object()
            .expect("renamed")
            .iter()
            .map(|(new, old)| (new.as_str(), text(old)))
            .collect();
        Self {
            protocol,
            serializers,
            serializer_ids,
            enums,
            types,
            root,
            particles,
            renamed,
        }
    }

    pub fn serializer(&self, id: i32) -> Option<Kind> {
        self.serializers.get(usize::try_from(id).ok()?).copied()
    }

    pub fn serializer_id(&self, kind: Kind) -> Option<i32> {
        self.serializer_ids.get(&kind).copied()
    }

    /// The constants of an enum kind in ordinal order.
    pub fn constants(&self, kind: Kind) -> &[&'static str] {
        self.enums.get(&kind).map_or(&[], Vec::as_slice)
    }

    /// The fields of an entity type by name, in index order.
    pub fn fields(&self, type_name: &str) -> Option<&[Field]> {
        self.types.get(data::strip(type_name)).map(Vec::as_slice)
    }

    /// The fields every entity type has.
    pub fn root(&self) -> &[Field] {
        &self.root
    }

    pub fn type_names(&self) -> impl Iterator<Item = &'static str> + '_ {
        self.types.keys().copied()
    }

    /// The options type of a particle, or `None` for a particle without
    /// options.
    pub fn particle_options(&self, particle: &str) -> Option<&'static str> {
        self.particles.get(data::strip(particle)).copied()
    }
}

/// The entity tables of `protocol`.
pub fn tables(protocol: i32) -> &'static Tables {
    static TABLES: OnceLock<Mutex<HashMap<i32, &'static Tables>>> = OnceLock::new();
    let mut tables = TABLES.get_or_init(Default::default).lock().unwrap();
    tables
        .entry(protocol)
        .or_insert_with(|| Box::leak(Box::new(Tables::load(protocol))))
}

/// Where one sender field goes in the receiver's protocol.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Target {
    pub index: u8,
    pub from: Kind,
    pub to: Kind,
    pub key: &'static str,
}

/// Sender index -> receiver field for one entity type, or for the fields
/// all entities share when the type is unknown.
#[derive(Debug, Default)]
pub struct Remap {
    pub targets: Vec<Option<Target>>,
    /// Every field keeps its index and serializer kind.
    pub identity: bool,
}

impl Remap {
    pub fn get(&self, index: u8) -> Option<Target> {
        self.targets.get(usize::from(index)).copied().flatten()
    }
}

/// The index remapping for an entity of type `from_type` in protocol `from`
/// that the receiver on protocol `to` knows as `to_type`. With a stand-in
/// type only the fields both types have survive; `None` types (an entity
/// spawned before tracking began) keep only the fields every entity has.
pub fn remap(from: i32, to: i32, from_type: Option<&str>, to_type: Option<&str>) -> &'static Remap {
    type Key = (i32, i32, Option<String>, Option<String>);
    static CACHE: OnceLock<Mutex<HashMap<Key, &'static Remap>>> = OnceLock::new();
    let key = (
        from,
        to,
        from_type.map(str::to_owned),
        to_type.map(str::to_owned),
    );
    let mut cache = CACHE.get_or_init(Default::default).lock().unwrap();
    cache.entry(key).or_insert_with(|| {
        let (source, target) = (tables(from), tables(to));
        let sender = from_type
            .and_then(|name| source.fields(name))
            .unwrap_or(source.root());
        let receiver = to_type
            .and_then(|name| target.fields(name))
            .unwrap_or(target.root());
        let by_key: HashMap<&str, (usize, Kind)> = receiver
            .iter()
            .enumerate()
            .map(|(index, field)| (field.key, (index, field.kind)))
            .collect();
        let targets: Vec<Option<Target>> = sender
            .iter()
            .map(|field| {
                let (index, kind) = *by_key.get(field.key)?;
                Some(Target {
                    index: u8::try_from(index).ok().filter(|index| *index != 0xff)?,
                    from: field.kind,
                    to: kind,
                    key: field.key,
                })
            })
            .collect();
        let identity = sender.len() == receiver.len()
            && targets.iter().enumerate().all(|(index, target)| {
                target.is_some_and(|target| {
                    usize::from(target.index) == index && target.from == target.to
                })
            });
        Box::leak(Box::new(Remap { targets, identity }))
    })
}
